#!/usr/bin/env node
/**
 * yaPDP states manifest drift test.
 *
 * Verifies the committed states/manifest.json (generated by
 * tools/gen-state-manifest.js):
 *   1. it lists exactly the *.state.zst files present in states/ — a state
 *      added or removed without regenerating the manifest would leave the
 *      quick-boot Scenario tab advertising a stale list (compare with
 *      tests/media-manifest.test.js, which does the same for media/);
 *   2. screenshots are stored as paths to states/previews/*.png, NOT as
 *      inline base64 data URIs. The manifest is fetched on every page load
 *      (src/quickboot.js fetchStateManifest), and 230 KB of base64 pushed
 *      the startup loading gate past its e2e budget (tests/e2e-startup-cls.js);
 *      a return to inlining regresses the cold start;
 *   3. every preview file a manifest entry points at exists on disk — a
 *      missing thumbnail would render as a broken image in the dialog.
 *
 * This file is different from tests/state-manifest.test.js, which drives the
 * tools/state-manifest.js CLI (extract/replace of the manifest stored INSIDE
 * a .state.zst). Keep the two names apart.
 *
 * Run with:  node tests/states-manifest.test.js
 *
 * Exit code 0 = all tests passed, non-zero = failure.
 */
"use strict";

const fs = require("fs");
const path = require("path");
const assert = require("assert");

const ROOT = path.join(__dirname, "..");
const STATES = path.join(ROOT, "states");
const MANIFEST = path.join(STATES, "manifest.json");

// --- 1. Manifest matches the states directory -------------------------------
{
    assert.ok(fs.existsSync(MANIFEST),
        "states/manifest.json should exist — run node tools/gen-state-manifest.js");

    const manifest = JSON.parse(fs.readFileSync(MANIFEST, "utf8"));
    assert.ok(Array.isArray(manifest), "manifest should be an array of entries");

    const expected = fs.readdirSync(STATES)
        .filter((f) => /\.state\.zst$/.test(f) && !f.startsWith("."))
        .sort();
    const listed = manifest.map((e) => e.file).sort();

    assert.deepStrictEqual(JSON.parse(JSON.stringify(listed)), expected,
        "manifest should list exactly the states in states/ " +
        "(regenerate with node tools/gen-state-manifest.js)");

    assert.strictEqual(new Set(manifest.map((e) => e.file)).size,
        manifest.length, "manifest should not contain duplicate state files");
}

// --- 2. Screenshots are paths, never inline base64 ---------------------------
{
    const manifest = JSON.parse(fs.readFileSync(MANIFEST, "utf8"));
    for (const entry of manifest) {
        for (const key of ["screenshot", "screenshotFull"]) {
            const v = entry[key];
            assert.ok(v === null || typeof v === "string",
                entry.file + ": " + key + " should be null or a path string");
            if (typeof v === "string") {
                assert.ok(!/^data:/.test(v),
                    entry.file + ": " + key + " must not inline a base64 data " +
                    "URI — the manifest is fetched on every load and ~230 KB of " +
                    "base64 delayed the startup gate past its budget " +
                    "(tests/e2e-startup-cls.js). Store paths under states/previews/");
                assert.ok(v.startsWith("previews/"),
                    entry.file + ": " + key + " should start with \"previews/\"");
            }
        }
    }
}

// --- 3. Every preview the manifest names exists on disk ----------------------
{
    const manifest = JSON.parse(fs.readFileSync(MANIFEST, "utf8"));
    for (const entry of manifest) {
        for (const key of ["screenshot", "screenshotFull"]) {
            const v = entry[key];
            if (typeof v !== "string") continue;
            assert.ok(fs.existsSync(path.join(STATES, v)),
                entry.file + ": " + key + " points at " + v +
                " which is missing from disk (regenerate the manifest)");
        }
    }
}

// --- 4. A regeneration never overwrites an existing full preview ------------
// tools/gen-state-manifest.js treats an already-written -full.png as
// operator-owned (a hand-placed or otherwise improved screenshot): the next
// run must keep it AND derive the thumbnail from it, not from the in-state
// screenshot. This runs against a throwaway directory, so the real
// states/previews/ stays untouched.
async function testFullPreviewSurvivesRegeneration() {
    const os = require("os");
    const { writePreviews, screenshotBuffer } = require(
        path.join(ROOT, "tools", "gen-state-manifest.js"));

    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "yapdp-states-preview-"));
    try {
        // One in-state screenshot so the fallback path works.
        const inState = "data:image/png;base64," +
            Buffer.from(await genPng(320, 200, "blue")).toString("base64");
        const manifest = { screenshot: inState };

        // First run: no preview files yet -> both are written from the state.
        const first = await writePreviews("probe.state.zst", manifest, tmp);
        assert.strictEqual(typeof first.small, "string",
            "first run should write a small preview");
        assert.ok(fs.readFileSync(path.join(tmp, "probe-full.png")).length > 0,
            "first run should write a full preview");

        // Operator replaces the full preview with one from elsewhere.
        const operatorFull = await genPng(640, 400, "red");
        fs.writeFileSync(path.join(tmp, "probe-full.png"), operatorFull);

        // Second run: the full file must survive byte-for-byte...
        const second = await writePreviews("probe.state.zst", manifest, tmp);
        assert.strictEqual(second.full, first.full,
            "the manifest paths must not change between runs");
        const fullAfter = fs.readFileSync(path.join(tmp, "probe-full.png"));
        assert.strictEqual(fullAfter.length, operatorFull.length,
            "an existing full preview must not be overwritten by regeneration");

        // ...and the thumbnail must be derived from the operator's full file,
        // not from the state's own screenshot (red, not blue).
        const smallStats = await pngMean(path.join(tmp, "probe-small.png"));
        assert.ok(smallStats.red > smallStats.blue,
            "the thumbnail must be regenerated from the existing full preview " +
            "(dominant channel " + (smallStats.red > smallStats.blue ? "red" : "blue") + ")");
    } finally {
        fs.rmSync(tmp, { recursive: true, force: true });
    }

    // The pure helper is exported and callable by tests.
    assert.strictEqual(typeof screenshotBuffer, "function",
        "gen-state-manifest.js should export screenshotBuffer for tests");
}

// --- helpers ----------------------------------------------------------------

// Deterministic solid-color PNG buffer via sharp (a devDependency of this
// repo, used by the manifest generator itself).
async function genPng(width, height, color) {
    const sharp = require("sharp");
    return await sharp({
        create: { width, height, channels: 3,
                  background: color === "red" ? { r: 255, g: 0, b: 0 }
                             : { r: 0, g: 0, b: 255 } },
    }).png().toBuffer();
}

// Mean RGB of a PNG, as a simple {red, green, blue} object.
async function pngMean(file) {
    const sharp = require("sharp");
    const s = await sharp(file).stats().catch(() => null);
    if (!s) return { red: 0, green: 0, blue: 0 };
    const c = s.channels;
    return { red: c[0] && c[0].mean || 0, green: c[1] && c[1].mean || 0,
             blue: c[2] && c[2].mean || 0 };
}

// The manifest checks above are synchronous; the writePreviews test is not.
(async function run() {
    await testFullPreviewSurvivesRegeneration();
    console.log("states-manifest tests passed");
})().catch((e) => { console.error(e); process.exit(1); });